export default "# NetHack 5.0 sysconf $NHDT-Date: 1777240863 2026/04/26 22:01:03 $ $NHDT-Branch: to500 $:$NHDT-Revis" +
    "ion: 1.47 $\n# Copyright (c) 2015 by Kenneth Lorber, Kensington, Maryland\n# NetHack may be freely red" +
    "istributed.  See license for details.\n#\n# Sample sysconf file.\n# The sysconf file is only used if Ne" +
    "tHack is compiled with SYSCF defined.\n# It can be used to augment or override certain settings compi" +
    "led into the\n# program.\n#\n# This file can also be used to set local system defaults for run-time\n# o" +
    "ptions, using the same syntax as an individual user's ./nethackrc file.\n\n# Which users can use debug" +
    " mode (aka wizard mode; accessed via '-D' command\n# line flag or OPTIONS=playmode:debug in the runti" +
    "me options config file).\n# A value of * allows anyone to enter debugging mode.\nWIZARDS=*\n\n# Which us" +
    "ers can use explore mode (aka discover mode; accessed via '-X'\n# command line flag or OPTIONS=playmo" +
    "de:explore in runtime options file or\n# via '#exploremode' command during normal play).  Same syntax" +
    " as WIZARDS.\nEXPLORERS=*\n\n# Users allowed to use the '!' (shell escape) and '^Z' (suspend process)\n#" +
    " commands to temporarily leave the game and enter a shell process.\n# (To resume play, use the shell " +
    "command 'exit' (for most shells) to\n# return from '!' or the shell command 'fg' to return from '^Z'." +
    "\n# For the typical multi-user system where players have access to a shell\n# prompt when logged in an" +
    "d run the game from their own username, a value\n# of 'SHELLERS=*' is appropriate.  However, some ine" +
    "xperienced players\n# occasionally get stuck outside the game by accidentally typing '!' or\n# '^Z' du" +
    "ring play and not knowing how to go back.)\n# Uses the same syntax as the WIZARDS and EXPLORERS optio" +
    "ns above.\n#SHELLERS=\n\n# Execute this program whenever a new message-window message is shown.\n# The p" +
    "rogram will get the message text as the only parameter.\n#MSGHANDLER=/usr/bin/espeak\n\n# If the user n" +
    "ame is found in this list, prompt for username instead.\n# Uses the same syntax as the WIZARDS option" +
    " above.\n# A public server should probably disable this.\n# [\"ec2-user\" is the default user name on Am" +
    "azon Linux]\nGENERICUSERS=play player game games nethack nethacker ec2-user\n\n# Use the player name fo" +
    "r matching WIZARDS, EXPLORERS and SHELLERS,\n# instead of the user's login name.\n#CHECK_PLNAME=1\n\n# L" +
    "imit the number of simultaneous games (see also nethack.sh).\n# Valid values are 0-25.\n# Commenting t" +
    "his out or setting the value to 0 constructs lock files\n# with UID and playername, so each user may " +
    "have one game at a time,\n# but number of different players is not limited.\n# Setting this to any oth" +
    "er value constructs the lock files with\n# letter and \"lock\" (eg. alock, block, ...)\nMAXPLAYERS=10\n\n#" +
    " If not null, added to string \"To get local support, \" in the support\n# information help.\n#SUPPORT=c" +
    "all Izchak at extension 42.\n\n# If not null, displayed at the end of a panic-save sequence.\n#RECOVER=" +
    "Run the recover program.\n\n# Uncomment the next line to disable the SEDUCE option, causing succubi an" +
    "d\n# incubi to use nymphs' charm behavior rather than their own seduce behavior.\n#SEDUCE=0\n\n# Uncomme" +
    "nt the next line to enable some accessibility features such\n# as S_hero_override and S_pet_override " +
    "symbols for screen readers\n# in the user config file.\n#ACCESSIBILITY=1\n\n# Uncomment to disable savef" +
    "ile UID checking.\n#CHECK_SAVE_UID=0\n\n# Record (high score) file options.\n# CAUTION: changing these a" +
    "fter people have started playing games can\n#  lead to lost high scores!\n# Maximum entries for one pe" +
    "rson.\n#PERSMAX=10\n# Maximum entries in the record file.\n#ENTRYMAX=100\n# Minimum points to get an ent" +
    "ry.\n#POINTSMIN=1\n# Determine identity of \"person\" in the score file with name (0) or\n# numeric (1) u" +
    "ser id.\n#PERS_IS_UID=1\n\n# Help menu control; 0 - include \"command line usage\" entry in help menu;\n# " +
    "1 - suppress it from the menu.  Does not affect 'nethack --usage' when\n# player has access to the co" +
    "mmand line.\n#HIDEUSAGE=0\n\n# Maximum number of score file entries to use for random statue names\n#MAX" +
    "_STATUENAME_RANK=10\n\n# Use \"Live logging\" for important events (achievements, wishes, etc)\n# Only av" +
    "ailable if NetHack was compiled with LIVELOG.\n# Only really meaningful for public servers or debuggi" +
    "ng.\n# See the log in-game with #chronicle -command.\n# Bitmask for kinds of things you want to log - " +
    "combine the following values\n# as desired.\n# 0x0000 - No live logging (default)\n# 0x0001 - Wishes\n# " +
    "0x0002 - Significant achievements (complete sokoban, perform invocation, etc)\n# 0x0004 - Kill, destr" +
    "oy or bribe a unique monster.\n# 0x0008 - Significant religious events (sacrifice gifts, crowning)\n# " +
    "0x0010 - Life-saving\n# 0x0020 - Break conduct - see also LLC_TURNS below.\n# 0x0040 - Artifact obtain" +
    "ed (#name Sting, dip for Excalibur)\n# 0x0080 - Genocides\n# 0x0100 - Murder of tame pet\n# 0x0200 - Ch" +
    "anged alignment temporarily or permanently\n# 0x0400 - Log URL for dumplog if ascended\n# 0x0800 - Log" +
    " dumplog url for all games\n# 0x1000 - Log 'minor' achievements - can be spammy\n# 0x2000 - Spoiler ev" +
    "ent; can include in livelog but hidden from #chronicle\n# 0x4000 - Include as 'major' event in dumplo" +
    "g; can be hidden from livelog\n# 0x8000 - Livelog debug msgs\n#LIVELOG=0x1FFF\n\n# Show debugging inform" +
    "ation originating from these source files.\n# Use '*' for all, or list source files separated by spac" +
    "es.\n# Only available if game has been compiled with DEBUG, and can be\n# overridden via DEBUGFILES en" +
    "vironment variable.\n#DEBUGFILES=*\n\n# Save end of game dump log to this file.\n# Only available if Net" +
    "Hack was compiled with DUMPLOG\n# Allows following placeholders:\n#   %% literal '%'\n#   %v version (e" +
    "g. \"NetHack 5.0.0-0\")\n#   %u game UID\n#   %t game start time, UNIX timestamp format\n#   %T current t" +
    "ime, UNIX timestamp format\n#   %d game start time, YYYYMMDDhhmmss format\n#   %D current time, YYYYMM" +
    "DDhhmmss format\n#   %n player name\n#   %N first character of player name\n#DUMPLOGFILE=/tmp/nethack.%" +
    "n.%d.log\n\n# Number of bones file pools.\n# The pool you belong to is determined at game start. You wi" +
    "ll\n# load and save bones only from that pool. Generally useful\n# for public servers only.\n# Changing" +
    " this might make existing bones inaccessible.\n# Disabled by setting to 0, or commenting out.\n#BONES_" +
    "POOLS=10\n\n# Try to get more info in case of a program bug or crash.  Only used\n# if the program is b" +
    "uilt with the PANICTRACE compile-time option enabled.\n# By default PANICTRACE is enabled if (NH_DEVE" +
    "L_STATUS != NH_STATUS_RELEASED),\n# otherwise disabled.\n# Using GDB can get more information and work" +
    "s on more systems but requires\n# 'gdb' be available; using LIBC only works if NetHack is linked with" +
    " a\n# libc that supports the backtrace(3) API.  Both require certain compilation\n# options.  See src/" +
    "end.c and sys/unix/hints/* for more information.\n# Values are priorities: 0 - do not use this method" +
    ", 1 - low priority,\n# 2 - high priority.  Non-zero priority methods are tried in order.\n\n# URL loade" +
    "d for creating reports to the NetHack DevTeam\n#CRASHREPORTURL=https://nethack.org/links/cr-5.0.0.htm" +
    "l\n\n# 'portable_device_paths' is only supported for Windows.  Starting with\n# 3.6.3, nethack on Windo" +
    "ws treats the folder containing nethack.exe and\n# nethackW.exe as read-only and puts data files whic" +
    "h are generated or\n# modified during play or by the user in assorted folders derived from\n# user nam" +
    "e.  3.6.4 added PORTABLE_DEVICE_PATHS to allow reverting to\n# the old behavior of having the run-tim" +
    "e configuration file and other\n# data in the same directory as the executable so that the whole thin" +
    "g\n# can be moved from one machine to another (flash drive or perhaps cloud)\n# without updating folde" +
    "r paths.\n#PORTABLE_DEVICE_PATHS=0\n\n# Ordinary run-time options can be set here to override the built" +
    "in-in\n# default values.  Unlike all the SYSCF values above, individual users\n# can override the over" +
    "ridden options set here by choosing their own\n# option settings via NETHACKOPTIONS in their environm" +
    "ent or via\n# ~/.nethackrc run-time configuration file.\n#OPTIONS=!autopickup,fruit:tomato,symset:DECg" +
    "raphics\n\n#eof\n";
